data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_02a56206cde52df8016aecc68e36fc87d2a25cb1b34744122b","logprobs":[],"output_index":0,"sequence_number":655,"text":"<title>Coffee menu</title>\n<meta name=\"idea\" content=\"A welcoming coffee menu with quick category filters and clear ordering actions\">\n<nav aria-label=\"Main navigation\">\n  <a href=\"#\" data-action=\"@menu\">Menu</a>\n  <a href=\"#\" data-action=\"@orders: Order history screen for a coffee shop app\">Orders</a>\n  <a href=\"#\" data-action=\"@rewards: Rewards screen showing points and perks in a coffee shop app\">Rewards</a>\n</nav>\n<header>\n  <small>GOOD MORNING · YOUR NEIGHBORHOOD COFFEE SHOP</small>\n  <h1>Find your favorite</h1>\n  <p>Made fresh, just for you.</p>\n</header>\n<label for=\"category\">Browse</label>\n<select id=\"category\">\n  <option>All drinks</option>\n  <option>Espresso</option>\n  <option>Cold</option>\n</select>\n<section id=\"drinks\">\n  <article data-kind=\"Espresso\">\n    <small>ESPRESSO · 4.8 ★</small>\n    <h2>Oat Milk Latte</h2>\n    <p>Smooth espresso with creamy oat milk.</p>\n    <p><strong>$4.75</strong></p>\n    <button data-action=\"@oat-latte-details: Item details for an oat milk latte in a coffee shop ordering app\">Details</button>\n    <button data-action=\"@order-checkout: Checkout screen for a coffee shop app with one oat milk latte in the cart\">Add to order</button>\n  </article>\n  <article data-kind=\"Cold\">\n    <small>COLD · 4.7 ★</small>\n    <h2>Vanilla Cold Brew</h2>\n    <p>Slow-steeped coffee with house vanilla.</p>\n    <p><strong>$4.50</strong></p>\n    <button data-action=\"@vanilla-cold-brew-details: Item details for vanilla cold brew in a coffee shop ordering app\">Details</button>\n    <button data-action=\"@order-checkout: Checkout screen for a coffee shop app with one vanilla cold brew in the cart\">Add to order</button>\n  </article>\n  <article data-kind=\"Espresso\">\n    <small>ESPRESSO · 4.9 ★</small>\n    <h2>Caramel Cappuccino</h2>\n    <p>Rich espresso, silky foam, caramel.</p>\n    <p><strong>$4.95</strong></p>\n    <button data-action=\"@caramel-cappuccino-details: Item details for a caramel cappuccino in a coffee shop ordering app\">Details</button>\n    <button data-action=\"@order-checkout: Checkout screen for a coffee shop app with one caramel cappuccino in the cart\">Add to order</button>\n  </article>\n</section>\n<script>\nconst category=document.querySelector(\"#category\");\ncategory.addEventListener(\"input\",()=>document.querySelectorAll(\"#drinks article\").forEach(card=>card.hidden=category.value!==\"All drinks\"&&card.dataset.kind!==category.value));\n</script>"}

